#!/usr/bin/env bash
# The evaluation's headline tables, regenerated by one run from one commit, with the code that made them written next to them.
# It refuses to run unless the tool and the Graal fork are exactly a commit and the builder is not older than the fork's sources:
# what provenance.sh records as uncommitted changes, untracked files, a stale builder, or no stamp at all. Run it on pontos04
# (after sync-pontos.sh from a clean checkout), alone: the timed stages wait for a quiet machine.
#
#   scripts/evaluation/reproduce.sh --list                  # the stages
#   scripts/evaluation/reproduce.sh                         # the default stages (about 2 hours)
#   scripts/evaluation/reproduce.sh loads time              # chosen stages
#   scripts/evaluation/reproduce.sh all                     # every stage, the long ones too (many hours)
#   scripts/evaluation/reproduce.sh --check provenance.txt  # only the decision: is this code a commit? (exit status 1 if it is not)
#   ALLOW_DIRTY=1 scripts/evaluation/reproduce.sh shapes    # for testing the script: the results are marked NOT-REPRODUCIBLE
#   THREAD_ESCAPE=off scripts/evaluation/reproduce.sh       # the same stages with no model of concurrency anywhere: no thread escape,
#                                                           # every lock and volatile access counts as ordering this thread with
#                                                           # another, nothing is elided. The stages loads, time, ceiling, cost (default),
#                                                           # control, javac and frameworks (these three: graal and fields only); results
#                                                           # in out/reproduction/<UTC time>-<tool commit>-no-thread-escape/
#
# The results are in out/reproduction/<UTC time>-<tool commit>/: provenance.txt (which code), one <stage>.txt for each stage
# (the commands' tables, as printed), and SUMMARY.txt (the stages, their status and time). The builds themselves stay in out/.
describe() {
    cat <<'EOF'
loads       loads left by Graal in the designed programs and in AWFY at -O2: graal, fields, objects (evaluation §3)
time        AWFY at -O3: graal and fields built 4 times, timed together with an A/A pair; loads left per build (§3, §4, F73)
ceiling     AWFY at -O3 with the ceiling: loads left and run times with an A/A pair (§3.1)
cost        build time, our steps, peak RSS of AWFY in every configuration, 5 rounds (§7)
shapes      lock and volatile shapes: Graal's image against the one that removes what thread escape proves (§8.5)
control     (not by default) control flow and loops left by graal, fields, objects: blocks, edges, ifs, exception edges, and the loads
            that left a loop, in the designed programs and AWFY at -O3, built with source positions (§3.3)
matrix      (long) thread escape on the concurrency examples, every analysis and set of assumptions (§8.3)
javac       (long) javac: cost of the field kill sets, the cutoff and lock removal, 3 rounds, and the time it takes to compile (§7, §8.4.2);
            with THREAD_ESCAPE=off: graal and fields, 3 rounds, loads left, and the time javac takes to compile with each image
frameworks  (long) PetClinic and three Barista servers: builds, removable sites, PetClinic under load (§8.6, §8.7);
            needs ~/eval/petclinic and ~/eval/barista (bundles copied from the laptop);
            with THREAD_ESCAPE=off: graal and fields, 3 rounds, on PetClinic and eleven Barista applications (cost, loads left),
            and PetClinic under load with the images of all rounds
EOF
}

# Whether the code in a provenance.txt is exactly a commit: no changed tracked files, no untracked ones, no warning that the
# builder is older than the sources, and a stamp for both trees.
refusal() {  # provenance.txt
    local reasons
    reasons=$(grep -E 'uncommitted: [1-9]|, [1-9][0-9]* untracked|WARNING|no history and no stamp' "$1" || true)
    [[ -z $reasons ]] && return 0
    echo "refusing to run: the code is not exactly a commit, or the builder is not made from it:"
    sed 's/^/    /' <<< "$reasons"
    return 1
}

# these two need nothing built: they come before env.sh, which wants the GraalVM
case ${1:-} in
    --list) describe; exit 0 ;;
    --check) refusal "${2:?usage: reproduce.sh --check <provenance.txt>}"; exit $? ;;
esac

source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/../../graal-native/env.sh"
source "$HERE/provenance.sh"
export PATH="$GRAALVM/bin:$PATH"  # programs/*/build.sh compile with the javac on the path

DEFAULT_STAGES=(loads time ceiling cost shapes)
ALL_STAGES=(loads time ceiling cost shapes control matrix javac frameworks)
NO_CONCURRENCY=
if [[ ${THREAD_ESCAPE:-on} == off ]]; then
    # the stages that remove locks or read what thread escape found have nothing to run without it
    NO_CONCURRENCY=1
    DEFAULT_STAGES=(loads time ceiling cost)
    ALL_STAGES=(loads time ceiling cost control javac frameworks)
fi
BARISTA_APPS=(vanilla-hello-world vertx-hello-world micronaut-hello-world micronaut-shopcart micronaut-similarity helidon-hello-world
              dropwizard-hello-world play-scala-hello-world ktor-hello-world spring-hello-world spring-petclinic)  # not the two Quarkus ones: they fail without the feature too

wait_quiet() {  # the timings are of a machine with nothing else running
    while [[ $(cut -d. -f1 /proc/loadavg) -ge 2 ]]; do sleep 15; done
    echo "machine quiet at $(date +%T), load $(cut -d' ' -f1-3 /proc/loadavg)"
}

counts() { uv run --project "$REPO" python "$SCRIPTS/evaluation/counts.py" "$@"; }
control_flow() { uv run --project "$REPO" python "$SCRIPTS/evaluation/control_flow.py" "$@"; }
load_split() { uv run --project "$REPO" python "$SCRIPTS/evaluation/load_split.py" "$@"; }

stage_loads() {
    local p
    for p in LoadStoreElimination Signatures Aliasing Allocation Awfy; do
        local tag=repro; [[ $p == Awfy ]] && tag=repro-o2
        ONLY="graal fields" TAG=$tag "$HERE/run.sh" "$p"
        ALLOCSENS=1 ONLY="graal fields objects" TAG=$tag "$HERE/run.sh" "$p"
    done
    for p in examples signatures aliasing allocation awfy; do
        local tag=repro; [[ $p == awfy ]] && tag=repro-o2
        echo "== $p, default analysis"; counts "$HERE/out/$p-$tag"/{graal,fields}/counts.txt
        [[ $p == awfy ]] || { echo "-- by kind of method (controls, unchanged, reduced)"; load_split "$HERE/out/$p-$tag"/{graal,fields}/counts.txt; }
        echo "== $p, allocation sites"; counts "$HERE/out/$p-allocsens-$tag"/{graal,fields,objects}/counts.txt
    done
}

stage_time() {
    "$SCRIPTS/evaluation/awfy-repeat.sh" 4 5
}

stage_ceiling() {
    ONLY="graal fields ceiling" TAG=repro-ceil EXTRA="-O3 -H:+AOTTrivialInline" "$HERE/run.sh" Awfy
    local o="$HERE/out/awfy-repro-ceil"
    echo "== loads left"; counts "$o"/{graal,fields,ceiling}/counts.txt
    grep "left out" "$o/ceiling/timings.txt"
    wait_quiet
    echo "== run time (the first image twice is the noise)"
    taskset -c 4-7 uv run --project "$REPO" python "$REPO/programs/awfy/time.py" --image "graal=$o/graal/awfy-repro-ceil" \
        --image "graal-again=$o/graal/awfy-repro-ceil" --image "fields=$o/fields/awfy-repro-ceil" --image "ceiling=$o/ceiling/awfy-repro-ceil"
}

stage_cost() {
    REPEATS=${COST_REPEATS:-5} "$SCRIPTS/evaluation/cost.sh" Awfy  # COST_REPEATS=1 to test the stage
    uv run --project "$REPO" python "$SCRIPTS/evaluation/cost.py" "$HERE/out" awfy
}

stage_control() {
    local p tag=ctl positions="-H:+TrackNodeSourcePosition" extra
    for p in LoadStoreElimination Signatures Aliasing Allocation Awfy; do
        extra=$positions
        [[ $p != Awfy ]] || extra="-O3 -H:+AOTTrivialInline $positions"
        EXTRA=$extra ONLY="graal fields" TAG=$tag "$HERE/run.sh" "$p"
        ALLOCSENS=1 EXTRA=$extra ONLY="graal fields objects" TAG=$tag "$HERE/run.sh" "$p"
    done
    for p in examples signatures aliasing allocation awfy; do
        echo "== $p, default analysis"; control_flow "$HERE/out/$p-$tag"/{graal,fields}
        echo "== $p, allocation sites"; control_flow "$HERE/out/$p-allocsens-$tag"/{graal,fields,objects}
    done
}

stage_shapes() {
    wait_quiet
    "$SCRIPTS/evaluation/time_locks.sh" LockShapes
    "$SCRIPTS/evaluation/time_locks.sh" VolatileShapes
}

stage_matrix() {
    "$SCRIPTS/sharing/thread-escape.sh"
}

stage_javac() {
    local o="$HERE/out"
    if [[ -n $NO_CONCURRENCY ]]; then
        REPEATS=3 CONFIGS="graal fields" "$SCRIPTS/evaluation/cost-javac.sh"
        uv run --project "$REPO" python "$SCRIPTS/evaluation/cost_programs.py" "$o"
        echo "== loads left in javac's methods"
        counts "$o/javac-cost-graal-r1/graal/counts.txt" "$o/javac-cost-fields-r1/fields/counts.txt"
        rm -rf "$o/javac-aa-copy" && mkdir -p "$o/javac-aa-copy/graal" && cp "$o/javac-cost-graal-r1/graal/javac" "$o/javac-aa-copy/graal/javac"
        wait_quiet
        echo "== time javac takes to compile AWFY's sources (the A/A copy is the first image again; three builds of each configuration)"
        taskset -c 4-7 uv run --project "$REPO" python "$SCRIPTS/evaluation/time_javac.py" "$o"/javac-cost-graal-r{1,2,3} "$o/javac-aa-copy" \
            "$o"/javac-cost-fields-r{1,2,3} --runs 10
        return 0
    fi
    REPEATS=3 CONFIGS="graal fields" "$SCRIPTS/evaluation/cost-javac.sh"
    uv run --project "$REPO" python "$SCRIPTS/evaluation/cost.py" "$o" javac
    REPEATS=3 CONFIGS="graal-allocsens graalcutoff-allocsens graalflagscutoff-allocsens lockscutoff" "$SCRIPTS/evaluation/cost-javac.sh"
    uv run --project "$REPO" python "$SCRIPTS/evaluation/cost.py" "$o" javac-allocsens
    local r
    echo "== the locks the builds removed"
    for r in 1 2 3; do echo "round $r: $(grep -h 'locks removed' "$o/javac-allocsens-cost-lockscutoff-r$r/locks/timings.txt")"; done
    echo "== loads left in javac's own classes"
    counts "$o/javac-allocsens-cost-graal-r1/graal/counts.txt" "$o/javac-allocsens-cost-graalcutoff-r1/graal/counts.txt" \
        "$o/javac-allocsens-cost-graalflagscutoff-r1/graal/counts.txt" "$o/javac-allocsens-cost-lockscutoff-r1/locks/counts.txt"
    rm -rf "$o/javac-aa-copy" && mkdir -p "$o/javac-aa-copy/graal" && cp "$o/javac-allocsens-cost-graal-r1/graal/javac" "$o/javac-aa-copy/graal/javac"
    wait_quiet
    echo "== time javac takes to compile AWFY's sources (the second image is an A/A copy of the first)"
    taskset -c 4-7 uv run --project "$REPO" python "$SCRIPTS/evaluation/time_javac.py" "$o/javac-allocsens-cost-graal-r1" "$o/javac-aa-copy" \
        "$o/javac-allocsens-cost-graalcutoff-r1" "$o"/javac-allocsens-cost-graalflagscutoff-r{1,2,3} "$o"/javac-allocsens-cost-lockscutoff-r{1,2,3} --runs 10
}

stage_frameworks() {
    local app r
    if [[ -n $NO_CONCURRENCY ]]; then
        local o="$HERE/out"
        for r in 1 2 3; do
            TAG=r$r "$SCRIPTS/frameworks/petclinic.sh" graal fields
            for app in "${BARISTA_APPS[@]}"; do
                TAG=r$r "$SCRIPTS/frameworks/barista.sh" "$app" graal fields
            done
        done
        uv run --project "$REPO" python "$SCRIPTS/evaluation/cost_programs.py" "$o"
        wait_quiet
        echo "== PetClinic under load: three builds of each configuration, the first graal image twice (A/A)"
        python3 "$SCRIPTS/frameworks/petclinic_load.py" --image graal-1="$o/petclinic-r1/graal/image" --image graal-1-again="$o/petclinic-r1/graal/image" \
            --image graal-2="$o/petclinic-r2/graal/image" --image graal-3="$o/petclinic-r3/graal/image" \
            --image fields-1="$o/petclinic-r1/fields/image" --image fields-2="$o/petclinic-r2/fields/image" --image fields-3="$o/petclinic-r3/fields/image" \
            --runs 5 --seconds 30 --warmup 15 --clients 16
        return 0
    fi
    "$SCRIPTS/frameworks/petclinic.sh" graal fields graalflagscutoff lockscutoff
    for app in vanilla-hello-world vertx-hello-world micronaut-hello-world; do
        "$SCRIPTS/frameworks/barista.sh" "$app" graal fields locks lockscutoff
    done
    for r in "$HERE/out/petclinic/lockscutoff" "$HERE"/out/barista/*/locks "$HERE"/out/barista/*/lockscutoff; do
        echo "== why no lock is removable in $r"
        uv run --project "$REPO" python "$SCRIPTS/sharing/why_no_locks.py" "$r/locks/export.json"
    done
    wait_quiet
    local p="$HERE/out/petclinic"
    python3 "$SCRIPTS/frameworks/petclinic_load.py" --image graal-1="$p/graal/image" --image graal-1-again="$p/graal/image" --image fields="$p/fields/image" \
        --image flags="$p/graalflagscutoff/image" --image locks="$p/lockscutoff/image" --runs 5 --seconds 30 --warmup 15 --clients 16
}

main() {
    if [[ ${1:-} == --run ]]; then  # one stage, run by the script itself so that set -e holds in it
        "stage_${2:?}"
        return $?
    fi
    local stages=("$@") stage
    [[ ${#stages[@]} -gt 0 ]] || stages=("${DEFAULT_STAGES[@]}")
    [[ ${stages[0]} != all ]] || stages=("${ALL_STAGES[@]}")
    for stage in "${stages[@]}"; do
        declare -F "stage_$stage" > /dev/null || { echo "unknown stage $stage (see --list)" >&2; return 2; }
        if [[ -n $NO_CONCURRENCY && $stage =~ ^(shapes|matrix)$ ]]; then
            echo "stage $stage needs thread escape, and THREAD_ESCAPE=off leaves it out" >&2
            return 2
        fi
    done

    local commit
    commit=$(sed -n 's/^commit: \([0-9a-f]\{7\}\).*/\1/p' "$REPO/.synced-from" 2> /dev/null | head -1 || true)
    [[ -n $commit ]] || commit=$(git -C "$REPO" rev-parse --short HEAD 2> /dev/null || echo unknown)
    local results="$HERE/out/reproduction/$(date -u +%Y%m%dT%H%M%SZ)-$commit${NO_CONCURRENCY:+-no-thread-escape}"
    mkdir -p "$results"
    provenance "$results"
    [[ -z $NO_CONCURRENCY ]] || echo "configuration: THREAD_ESCAPE=off, so no thread escape, no lock or volatile facts, every acquire and release counts, nothing elided" >> "$results/provenance.txt"
    if ! refusal "$results/provenance.txt"; then
        if [[ ${ALLOW_DIRTY:-} != 1 ]]; then
            rm -rf "$results"
            return 1
        fi
        echo "ALLOW_DIRTY=1: going on, and these results are marked NOT-REPRODUCIBLE"
        echo "the code was not exactly a commit (ALLOW_DIRTY=1); see provenance.txt" > "$results/NOT-REPRODUCIBLE"
    fi
    echo "results in $results"

    local failed=() start status
    {
        echo "stage        status   seconds"
        for stage in "${stages[@]}"; do
            echo "== $stage ($(date +%T))" >&2
            start=$SECONDS
            status=ok
            set +e
            bash "${BASH_SOURCE[0]}" --run "$stage" 2>&1 | tee "$results/$stage.txt" >&2
            [[ ${PIPESTATUS[0]} -eq 0 ]] || status=FAILED
            set -e
            [[ $status == ok ]] || failed+=("$stage")
            printf '%-12s %-8s %s\n' "$stage" "$status" "$((SECONDS - start))"
        done
    } | tee "$results/SUMMARY.txt"
    [[ ${#failed[@]} -eq 0 ]] || { echo "failed: ${failed[*]}" >&2; return 1; }
}

main "$@"
